CREATE TABLE public.mac_wallets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, app_name text NOT NULL, owner_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.mac_wallets TO authenticated; GRANT ALL ON public.mac_wallets TO service_role; ALTER TABLE public.mac_wallets ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.mac_accounts(id uuid PRIMARY KEY, wallet_id uuid NOT NULL REFERENCES public.mac_wallets(id), name text NOT NULL, username text NOT NULL, role text NOT NULL CHECK(role IN ('admin','gestor','colaborador')), UNIQUE(wallet_id,username));
GRANT SELECT ON public.mac_accounts TO authenticated; GRANT ALL ON public.mac_accounts TO service_role; ALTER TABLE public.mac_accounts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.mac_stores(id text PRIMARY KEY, wallet_id uuid NOT NULL REFERENCES public.mac_wallets(id), name text NOT NULL);
GRANT SELECT ON public.mac_stores TO authenticated; GRANT ALL ON public.mac_stores TO service_role; ALTER TABLE public.mac_stores ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.mac_memberships(user_id uuid NOT NULL, store_id text NOT NULL REFERENCES public.mac_stores(id), role text NOT NULL CHECK(role IN ('admin','gestor','colaborador')), PRIMARY KEY(user_id,store_id));
GRANT SELECT ON public.mac_memberships TO authenticated; GRANT ALL ON public.mac_memberships TO service_role; ALTER TABLE public.mac_memberships ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.mac_wallet_access(w uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.mac_accounts WHERE id=auth.uid() AND wallet_id=w) $$;
CREATE FUNCTION public.mac_wallet_admin(w uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.mac_accounts WHERE id=auth.uid() AND wallet_id=w AND role='admin') $$;
CREATE FUNCTION public.mac_store_access(s text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.mac_memberships WHERE user_id=auth.uid() AND store_id=s) OR EXISTS(SELECT 1 FROM public.mac_stores WHERE id=s AND public.mac_wallet_admin(wallet_id)) $$;
CREATE POLICY wallet_read ON public.mac_wallets FOR SELECT TO authenticated USING(public.mac_wallet_access(id));
CREATE POLICY accounts_read ON public.mac_accounts FOR SELECT TO authenticated USING(public.mac_wallet_access(wallet_id));
CREATE POLICY stores_read ON public.mac_stores FOR SELECT TO authenticated USING(public.mac_store_access(id));
CREATE POLICY members_read ON public.mac_memberships FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.mac_stores s WHERE s.id=store_id AND public.mac_wallet_access(s.wallet_id)));
CREATE TABLE public.mac_documents(wallet_id uuid NOT NULL REFERENCES public.mac_wallets(id), key text NOT NULL, store_id text REFERENCES public.mac_stores(id), value jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(wallet_id,key));
GRANT SELECT ON public.mac_documents TO authenticated; GRANT ALL ON public.mac_documents TO service_role; ALTER TABLE public.mac_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_read ON public.mac_documents FOR SELECT TO authenticated USING((store_id IS NOT NULL AND public.mac_store_access(store_id)) OR (store_id IS NULL AND public.mac_wallet_admin(wallet_id)));
CREATE TABLE public.mac_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), wallet_id uuid NOT NULL REFERENCES public.mac_wallets(id), store_id text NOT NULL REFERENCES public.mac_stores(id), sender_id uuid NOT NULL, recipient_id uuid, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
GRANT SELECT,INSERT,UPDATE ON public.mac_messages TO authenticated; GRANT ALL ON public.mac_messages TO service_role; ALTER TABLE public.mac_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_read ON public.mac_messages FOR SELECT TO authenticated USING(public.mac_wallet_access(wallet_id) AND ((recipient_id IS NULL AND public.mac_store_access(store_id)) OR sender_id=auth.uid() OR recipient_id=auth.uid()));
CREATE POLICY messages_send ON public.mac_messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.mac_store_access(store_id) AND public.mac_wallet_access(wallet_id) AND (recipient_id IS NULL OR EXISTS(SELECT 1 FROM public.mac_accounts a WHERE a.id=recipient_id AND a.wallet_id=mac_messages.wallet_id)));
CREATE POLICY messages_edit ON public.mac_messages FOR UPDATE TO authenticated USING(sender_id=auth.uid()) WITH CHECK(sender_id=auth.uid());
CREATE TABLE public.mac_reads(message_id uuid NOT NULL REFERENCES public.mac_messages(id), user_id uuid NOT NULL, read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(message_id,user_id));
GRANT SELECT,INSERT ON public.mac_reads TO authenticated; GRANT ALL ON public.mac_reads TO service_role; ALTER TABLE public.mac_reads ENABLE ROW LEVEL SECURITY;
CREATE POLICY reads_own ON public.mac_reads FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY reads_insert ON public.mac_reads FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.mac_messages m WHERE m.id=message_id));
CREATE FUNCTION public.mac_put_document(w uuid,k text,s text,v jsonb,r integer) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE next_rev integer; BEGIN
 IF NOT public.mac_wallet_access(w) THEN RAISE EXCEPTION 'Sem acesso à carteira'; END IF;
 IF s IS NULL THEN IF NOT public.mac_wallet_admin(w) THEN RAISE EXCEPTION 'Apenas administrador'; END IF; ELSE IF NOT public.mac_store_access(s) OR NOT EXISTS(SELECT 1 FROM public.mac_stores WHERE id=s AND wallet_id=w) THEN RAISE EXCEPTION 'Sem acesso à loja'; END IF; END IF;
 INSERT INTO public.mac_documents(wallet_id,key,store_id,value,revision) VALUES(w,k,s,v,1) ON CONFLICT(wallet_id,key) DO UPDATE SET value=v, revision=mac_documents.revision+1,updated_at=now() WHERE mac_documents.revision=r RETURNING revision INTO next_rev;
 IF next_rev IS NULL THEN RAISE EXCEPTION 'CONFLICT'; END IF; RETURN next_rev; END $$;
REVOKE ALL ON FUNCTION public.mac_put_document(uuid,text,text,jsonb,integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.mac_put_document(uuid,text,text,jsonb,integer) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.mac_documents,public.mac_stores,public.mac_memberships,public.mac_messages;
CREATE TABLE public.mac_bootstrap_lock(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), owner_id uuid NOT NULL);
GRANT ALL ON public.mac_bootstrap_lock TO service_role; ALTER TABLE public.mac_bootstrap_lock ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.mac_reserve_bootstrap(u uuid) RETURNS void LANGUAGE sql SET search_path=public AS $$ INSERT INTO public.mac_bootstrap_lock(singleton,owner_id) VALUES(true,u) $$; REVOKE ALL ON FUNCTION public.mac_reserve_bootstrap(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.mac_reserve_bootstrap(uuid) TO service_role;